import React from 'react';
import { names } from '../data';

function Table({ range, onBackBtnClick, onCalculateBtnClick, onTipsChange, onShiftsChange, onResults }) {
    const { startDate, endDate } = range[0];
    const dateOption = { day: 'numeric' };
    const dayOption = { weekday: "short" };
    const startIndex = startDate.toLocaleDateString('en-US', dateOption);
    const endIndex = endDate.toLocaleDateString('en-US', dateOption);

    const datesArray = [];
    let currentDate = new Date(startDate);

    for (let i = +startIndex; i <= endIndex; i++) {
        let day = currentDate.toLocaleDateString('en-US', dayOption);

        datesArray.push({
            date: i,
            day: day
        })

        currentDate.setDate(currentDate.getDate() + 1);
    }

    function calculateTips(tips, shifts) {
        for (let tip in tips) {
          // Divide tip by percentage
          const morningTip = tip.morningTip * 0.6;
          const eveningTip = tip.eveningTip * 0.6;
          // Calculate total hours for a corresponding date by time
          let shiftsByDate = shifts.filter((shift) => shift.date === tip.date);
          let totalMorningHours = 0;
          let totalEveningHours = 0;
          shiftsByDate.map((shift) => {
            totalMorningHours = totalMorningHours + shift.morningHours;
            totalEveningHours = totalEveningHours + shift.eveningHours;
            return totalMorningHours;
          });
          shiftsByDate.map((shift) => {
            totalMorningHours = totalMorningHours + shift.morningHours;
            totalEveningHours = totalEveningHours + shift.eveningHours;
            return totalMorningHours;
          });
          // Calculate how much money in dollars per hour
          const morningRate = morningTip / totalMorningHours;
          const eveningRate = eveningTip / totalEveningHours;
          // Store results in the state
          shiftsByDate.map((shift => {
            const morningTip = morningRate * shift.morningHours;
            const eveningTip = eveningRate * shift.eveningHours;
            const totalHours = shift.morningHours + shift.eveningHours;

            onResults(shift.date, shift.name, morningTip, eveningTip, totalHours);
          }));
        }
      }

    return (
        <div className='wrapper'>
            <button className='button' onClick={onBackBtnClick}>Back</button>
            <div className='table-container'>
                <table id='table'>
                    {datesArray.map((date, dateKey) =>
                        <React.Fragment key={dateKey} >
                            <thead>
                                <tr>
                                    <th>{date.day} {date.date}</th>
                                    <th>
                                        <label>Morning Tip</label>
                                        <input
                                            type="number"
                                            defaultValue="0"
                                            onChange={(e) =>
                                                onTipsChange(date.date, "morningTip", e.target.value)
                                            }
                                        />
                                    </th>
                                    <th>
                                        <label>Evening Tip</label>
                                        <input
                                            type="number"
                                            defaultValue="0"
                                            onChange={(e) =>
                                                onTipsChange(date.date, "eveningTip", e.target.value)
                                            }
                                        />
                                    </th>
                                </tr>
                                <tr>
                                    <th>Name</th>
                                    <th>Hours - Morning</th>
                                    <th>Hours - Evening</th>
                                </tr>
                            </thead>
                            <tbody key={`tbody-${dateKey}`}>
                                {names.map((name, nameKey) =>
                                    <tr key={`row-${dateKey}-${nameKey}`}>
                                        <th>{name}</th>
                                        <th>
                                            <input
                                                type="number"
                                                defaultValue="0"
                                                onChange={(e) =>
                                                    onShiftsChange(date.date, name, "morningHours", e.target.value)
                                                }
                                            />
                                        </th>
                                        <th>
                                            <input
                                                type="number"
                                                defaultValue="0"
                                                onChange={(e) =>
                                                    onShiftsChange(date.date, name, "eveningHours", e.target.value)
                                                }
                                            />
                                        </th>
                                    </tr>
                                )}
                            </tbody>
                        </React.Fragment>
                    )}
                </table>
            </div>
            <button className='button' onClick={onCalculateBtnClick}>Calculate</button>
        </div>
    );
}

export default Table;
